-- Telegram 黑名单表
CREATE TABLE IF NOT EXISTS blacklist (
    id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    telegram_id BIGINT NOT NULL,
    type        TEXT NOT NULL,
    title       TEXT NOT NULL,
    username    TEXT NOT NULL,
    url         TEXT NOT NULL,
    reason_type TEXT NOT NULL,
    reason      TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT blacklist_telegram_key UNIQUE (type, telegram_id),
    CONSTRAINT blacklist_type_check CHECK (type IN ('channel', 'group', 'bot'))
);

COMMENT ON TABLE blacklist IS 'Telegram 黑名单表';

COMMENT ON COLUMN blacklist.id IS 'ID';
COMMENT ON COLUMN blacklist.telegram_id IS 'Telegram 唯一 ID';
COMMENT ON COLUMN blacklist.type IS '类型：频道（channel）、群组（group）或机器人（bot）';
COMMENT ON COLUMN blacklist.title IS '名称';
COMMENT ON COLUMN blacklist.username IS '用户名';
COMMENT ON COLUMN blacklist.url IS '链接';
COMMENT ON COLUMN blacklist.reason_type IS '黑名单原因分类';
COMMENT ON COLUMN blacklist.reason IS '黑名单原因说明';
COMMENT ON COLUMN blacklist.created_at IS '创建时间';
COMMENT ON COLUMN blacklist.updated_at IS '更新时间';

CREATE INDEX IF NOT EXISTS blacklist_username_idx
    ON blacklist (username);

CREATE INDEX IF NOT EXISTS blacklist_url_idx
    ON blacklist (url);

