-- 资源数据表


CREATE TABLE IF NOT EXISTS entries (
    id            BIGINT PRIMARY KEY,
    telegram_id   BIGINT,
    username      TEXT UNIQUE,
    url           TEXT NOT NULL UNIQUE,
    type          TEXT,
    title         TEXT,
    description   TEXT,
    avatar        TEXT,
    count         INTEGER,
    last_active   TIMESTAMPTZ,
    valid         BOOLEAN NOT NULL DEFAULT FALSE,
    private       BOOLEAN NOT NULL DEFAULT FALSE,
    keep          BOOLEAN NOT NULL DEFAULT FALSE,
    filter_reason TEXT,
    created_at    TIMESTAMPTZ NOT NULL,
    updated_at    TIMESTAMPTZ NOT NULL,
    clean_title   TEXT,
    clean_desc    TEXT,
    category      TEXT
);

COMMENT ON TABLE entries IS 'Telegram 资源数据';

COMMENT ON COLUMN entries.id IS '资源记录 ID';
COMMENT ON COLUMN entries.telegram_id IS 'Telegram ID';
COMMENT ON COLUMN entries.username IS '用户名';
COMMENT ON COLUMN entries.url IS '资源链接';
COMMENT ON COLUMN entries.type IS '资源类型';
COMMENT ON COLUMN entries.title IS '资源名称';
COMMENT ON COLUMN entries.description IS '资源简介';
COMMENT ON COLUMN entries.avatar IS '头像地址';
COMMENT ON COLUMN entries.count IS '订阅或成员数量';
COMMENT ON COLUMN entries.last_active IS '最后活跃时间';
COMMENT ON COLUMN entries.valid IS '链接是否有效';
COMMENT ON COLUMN entries.private IS '是否为私有资源';
COMMENT ON COLUMN entries.keep IS '是否保留';
COMMENT ON COLUMN entries.filter_reason IS '过滤原因';
COMMENT ON COLUMN entries.created_at IS '创建时间';
COMMENT ON COLUMN entries.updated_at IS '更新时间';
COMMENT ON COLUMN entries.clean_title IS '清洗后的名称';
COMMENT ON COLUMN entries.clean_desc IS '清洗后的简介';
COMMENT ON COLUMN entries.category IS '资源分类';

CREATE INDEX IF NOT EXISTS entries_telegram_id_idx
    ON entries (telegram_id);

CREATE INDEX IF NOT EXISTS entries_type_idx
    ON entries (type);

CREATE INDEX IF NOT EXISTS entries_category_idx
    ON entries (category);

