CREATE TABLE IF NOT EXISTS links (
    id         BIGINT PRIMARY KEY,
    url        TEXT NOT NULL UNIQUE,
    username   TEXT,
    name       TEXT,
    type_hint  TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

COMMENT ON TABLE links IS '采集到的 Telegram 链接';

COMMENT ON COLUMN links.id IS '链接记录 ID';
COMMENT ON COLUMN links.url IS '资源链接';
COMMENT ON COLUMN links.username IS '用户名';
COMMENT ON COLUMN links.name IS '资源名称';
COMMENT ON COLUMN links.type_hint IS '推断的资源类型';
COMMENT ON COLUMN links.created_at IS '创建时间';
COMMENT ON COLUMN links.updated_at IS '更新时间';

CREATE INDEX IF NOT EXISTS links_username_idx
    ON links (username);

